from collections import Counter
s=open('region.fasta').read().split('\n',1)[1].replace('\n','').upper()
n=len(s)
print("longest 6 of 8 identical:', check exact 8-mer repeats with distance")
k=8
cnt=Counter(s[i:i+k] for i in range(n-k+1))
rep={kmer:c for kmer,c in cnt.items() if c>1}
print(len(rep),"8-mers repeated >1x")
for kmer in list(rep)[:5]:
    print(kmer, rep[kmer])
# exact long repeats (len>=15)
print("\nexact repeats >=15bp:")
subs={}
hits=[]
for L in [20,18,16,15]:
    seen={}
    for i in range(n-L+1):
        sub=s[i:i+L]
        if sub in seen:
            hits.append((L, seen[sub]+1, i+1, sub))
        else:
            seen[sub]=i
    if hits:
        print('L=',L, hits[:10])
        break
# positions where_bases?
# AA/TT rich zones
print("\nA+T content per 50bp window (showing low-GC areas):")
lo=[]
for i in range(0,n-49,50):
    w=s[i:i+50]
    gc=(w.count('G')+w.count('C'))/50*100
    lo.append((i+1,gc))
lo.sort(key=lambda x:x[1])
for a,g in lo[:8]:
    print(a, "%.0f"%g)
